(() => {
  'use strict';
  const canvas = document.querySelector('#game');
  const ctx = canvas.getContext('2d');
  const mini = document.querySelector('#minimap');
  const mctx = mini.getContext('2d');
  const $ = (s) => document.querySelector(s);
  const W = 2800, H = 2050;
  const chars = {
    pip:{name:'Pip', color:'#e98b68', hat:'#f0c77b', trim:'#f6e8bd', glyph:'✿', speed:190},
    moss:{name:'Moss', color:'#638b68', hat:'#d6c18a', trim:'#e3e5c4', glyph:'❋', speed:158},
    wren:{name:'Wren', color:'#8a76a0', hat:'#d9b8cb', trim:'#f0d7c8', glyph:'✦', speed:213}
  };
  const state = { running:false, paused:false, char:'pip', x:680,y:890, facing:'down', frame:0, camera:{x:0,y:0}, keys:{}, collected:0, berries:0, boost:0, sound:false, questDone:false, toastTimer:0, dialogueOpen:false, discovered:new Set(), lastTime:0, elapsed:0 };
  const rand = (seed) => { let n=seed|0; return () => { n=(n*1664525+1013904223)|0; return (n>>>0)/4294967296; }; };
  const random = rand(1947);
  const glows = [{x:400,y:635},{x:835,y:590},{x:1060,y:1110},{x:1470,y:625},{x:1920,y:1100},{x:2260,y:520}].map((p,i)=>({...p,id:'g'+i,taken:false}));
  const berryBushes = [{x:520,y:1060},{x:920,y:440},{x:1540,y:1250},{x:1990,y:630},{x:2380,y:1420},{x:1240,y:430}].map((p,i)=>({...p,id:'b'+i,taken:false}));
  const npcs = [
    {id:'rowan',name:'Rowan',x:1170,y:900,color:'#bd8666',hat:'#e7c27c',glyph:'R',type:'rowan'},
    {id:'fenn',name:'Fenn',x:1780,y:650,color:'#788fa0',hat:'#d7d9bb',glyph:'F',type:'fenn'},
    {id:'mira',name:'Mira',x:2200,y:1340,color:'#987e9c',hat:'#ecc5a0',glyph:'M',type:'mira'}
  ];
  const props = [
    {id:'sign',x:758,y:785,r:32,label:'Valley sign'}, {id:'bridge',x:1170,y:1000,r:45,label:'Old bridge'},
    {id:'lookout',x:2380,y:450,r:48,label:'Sunset lookout'}, {id:'camp',x:1700,y:1300,r:48,label:'Mossy campfire'},
    {id:'door',x:1780,y:826,r:36,label:'Fenn’s cottage'}
  ];
  const trees=[];
  for(let i=0;i<165;i++){
    const x=70+random()*(W-140), y=70+random()*(H-140);
    // Leave the central trail and village clear, while keeping the forest pleasantly wild.
    if((x>300&&x<1050&&y>500&&y<1250)||(x>1030&&x<1340&&y>730&&y<1060)||(x>1560&&x<1930&&y>480&&y<930)) continue;
    const r=22+random()*19;
    trees.push({x,y,r,kind:random(),tone:random()});
  }
  const flowers=[];
  for(let i=0;i<230;i++) flowers.push({x:random()*W,y:random()*H,k:random(),s:1+random()*2});
  const keysDown = new Set();
  let audio;

  function resize(){
    const dpr=Math.min(window.devicePixelRatio||1,2), rect=canvas.getBoundingClientRect();
    canvas.width=Math.round(rect.width*dpr); canvas.height=Math.round(rect.height*dpr);
    ctx.setTransform(dpr,0,0,dpr,0,0);
  }
  window.addEventListener('resize',resize); resize();
  function notify(text){const el=$('#toast');el.textContent=text;el.classList.add('show');state.toastTimer=2.2;}
  function playTone(freq=520,duration=.08){if(!state.sound)return;try{audio ||= new (window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=freq;o.type='sine';g.gain.setValueAtTime(.055,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}catch(_){}}
  function setChar(id){state.char=id;const c=chars[id];$('#charName').textContent=c.name;$('#charAvatar').innerHTML=`<span>${c.glyph}</span>`;$('#charAvatar').style.color=c.color;document.querySelectorAll('.choice').forEach(b=>b.classList.toggle('active',b.dataset.char===id));}
  document.querySelectorAll('.choice').forEach(b=>b.addEventListener('click',()=>setChar(b.dataset.char)));
  $('#playBtn').addEventListener('click',()=>{state.running=true;$('#startOverlay').classList.add('hidden');notify('The valley is yours. Follow the little trail.');playTone(590,.16);canvas.focus?.();});
  $('#switchBtn').addEventListener('click',cycleCharacter);
  function cycleCharacter(){const ids=Object.keys(chars),next=ids[(ids.indexOf(state.char)+1)%ids.length];setChar(next);notify(`Now wandering as ${chars[next].name}.`);playTone(430,.08)}
  $('#soundBtn').addEventListener('click',()=>{state.sound=!state.sound;$('#soundBtn').textContent=state.sound?'♫':'♪';$('#soundBtn').style.background=state.sound?'rgba(246,219,153,.36)':'';if(state.sound)playTone(620,.1)});
  $('#resumeBtn').addEventListener('click',()=>togglePause(false));
  $('#dialogueClose').addEventListener('click',closeDialogue);
  function togglePause(force){state.paused=force??!state.paused;$('#pauseOverlay').classList.toggle('hidden',!state.paused);}
  function openDialogue(name,text,glyph='•',color='#dce7d6'){state.dialogueOpen=true;$('#dialogueName').textContent=name;$('#dialogueText').textContent=text;$('#dialogueAvatar').textContent=glyph;$('#dialogueAvatar').style.background=color;$('#dialogue').classList.remove('hidden');}
  function closeDialogue(){state.dialogueOpen=false;$('#dialogue').classList.add('hidden');}
  window.addEventListener('keydown',e=>{
    const k=e.key.toLowerCase(); if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();
    if(k==='escape'){if(state.dialogueOpen)closeDialogue();else if(state.running)togglePause();return;}
    if(!state.running||state.paused)return;
    if(k==='e'){interact();return;} if(k==='f'){snack();return;}
    if(k==='1')setChar('pip');if(k==='2')setChar('moss');if(k==='3')setChar('wren');
    keysDown.add(k);
  });
  window.addEventListener('keyup',e=>keysDown.delete(e.key.toLowerCase()));
  window.addEventListener('blur',()=>keysDown.clear());
  document.querySelectorAll('.touch-controls button').forEach(btn=>{
    const dir=btn.dataset.dir, map={up:'w',down:'s',left:'a',right:'d'}, key=map[dir];
    const down=e=>{e.preventDefault();keysDown.add(key)}, up=e=>{e.preventDefault();keysDown.delete(key)};
    btn.addEventListener('pointerdown',down);btn.addEventListener('pointerup',up);btn.addEventListener('pointercancel',up);btn.addEventListener('pointerleave',up);
  });
  function snack(){if(state.berries>0){state.berries--;state.boost=8;updateHUD();notify('A sweet berry! Your feet feel lighter for a bit.');playTone(700,.13)}else notify('No berries in your pockets yet.');}

