function snack(){if(state.berries>0){state.berries--;state.boost=8;updateHUD();notify('A sweet berry! Your feet feel lighter for a bit.');playTone(700,.13)}else notify('No berries in your pockets yet.');}
function updateHUD(){
  $('#capsCount').textContent=state.collected;$('#berriesCount').textContent=state.berries;
  $('#progressFill').style.width=`${Math.min(100,state.collected/3*100)}%`;
  $('#progressCount').textContent=state.questDone?'DONE':`${Math.min(3,state.collected)} / 3`;
  if(state.questDone){$('#questTitle').textContent='A light left on';$('#questText').textContent='The valley feels a little brighter tonight.';}
  else if(state.collected>=3){$('#questTitle').textContent='Back to Rowan';$('#questText').textContent='You found enough glowcaps. Meet Rowan at the old bridge.';}
}
function nearestThing(){let best=null,dist=Infinity;const all=[...npcs,...glows.filter(o=>!o.taken).map(o=>({...o,type:'glow'})),...berryBushes.filter(o=>!o.taken).map(o=>({...o,type:'berry'})),...props];
  for(const o of all){const d=Math.hypot(o.x-state.x,o.y-state.y);if(d<(o.type==='glow'||o.type==='berry'?54:75)&&d<dist){best=o;dist=d;}}return best;}
function interact(){if(state.dialogueOpen){closeDialogue();return;}const o=nearestThing();if(!o){notify('Nothing nearby — take the trail and see.');return;}
  if(o.type==='glow'){
    const target=glows.find(g=>g.id===o.id);target.taken=true;state.collected++;updateHUD();notify(`Glowcap tucked away · ${state.collected} of 3`);playTone(740,.12);return;
  }
  if(o.type==='berry'){
    const target=berryBushes.find(b=>b.id===o.id);target.taken=true;state.berries++;updateHUD();notify('A handful of valley berries. Press F for a little energy.');playTone(650,.1);return;
  }
  if(o.type==='rowan'){
    if(state.questDone)openDialogue('Rowan','Look at that — the path home glows like a little piece of the sky. You made this place feel like home.','R','#ecd9b2');
    else if(state.collected>=3){state.questDone=true;updateHUD();openDialogue('Rowan','These are perfect. I’ll hang them along the bridge for anyone walking home after dusk. Thank you, friend. Take this berry tart for the road!','R','#ecd9b2');state.berries+=2;updateHUD();playTone(790,.22);}
    else openDialogue('Rowan',`The old path gets a bit gloomy when evening comes. Could you find me three glowcaps? They bloom in the meadow and along the creek. You have ${state.collected} so far.`,`R`,'#ecd9b2');return;
  }
  if(o.type==='fenn'){openDialogue('Fenn','I’m making a map of every good place to sit and do absolutely nothing. There’s a lookout east of here — the view is worth the walk.','F','#dce6e4');return;}
  if(o.type==='mira'){openDialogue('Mira','The water here remembers every little thing. Toss a wish in the creek sometime. I think it keeps the kind ones.','M','#e8dce9');return;}
  if(o.id==='sign'){openDialogue('A hand-painted sign','MEADOW ←  ·  OLD BRIDGE ↑  ·  SUNSET LOOKOUT →  ·  TAKE THE LONG WAY.','⌖','#e8e5ce');return;}
  if(o.id==='bridge'){
    if(state.collected>=3&&!state.questDone){const row=npcs[0];state.x=row.x;state.y=row.y+45;openDialogue('Rowan','Oh, you found them! Just what the bridge needs.','R','#ecd9b2');}
    else openDialogue('The old bridge','Silver creek slides under the old boards. Somebody has carved a tiny star into the railing.','✳','#e5e3ce');return;
  }
  if(o.id==='lookout'){if(!state.discovered.has('lookout')){state.discovered.add('lookout');notify('A place to watch the day go by · discovered');playTone(620,.15)}else openDialogue('Sunset lookout','The whole valley fits in a pocket from up here. You can see the creek curl past the meadow.','☼','#f1e4c4');return;}
  if(o.id==='camp'){openDialogue('The little campfire','A warm place to rest. The fire pops once, like it knows a secret.','♨','#e7d2b2');return;}
  if(o.id==='door'){openDialogue('Fenn’s cottage','A little note is pinned to the door: “Out wandering. Back before the stars.”','⌂','#e3e7d8');}
}
function update(dt){
  state.elapsed+=dt;state.frame+=dt*8;if(state.boost>0)state.boost=Math.max(0,state.boost-dt);
  if(state.toastTimer>0){state.toastTimer-=dt;if(state.toastTimer<=0)$('#toast').classList.remove('show');}
  if(!state.running||state.paused||state.dialogueOpen)return;
  let dx=0,dy=0;if(keysDown.has('w')||keysDown.has('arrowup'))dy--;if(keysDown.has('s')||keysDown.has('arrowdown'))dy++;if(keysDown.has('a')||keysDown.has('arrowleft'))dx--;if(keysDown.has('d')||keysDown.has('arrowright'))dx++;
  if(dx||dy){const n=Math.hypot(dx,dy);dx/=n;dy/=n;state.facing=Math.abs(dx)>Math.abs(dy)?(dx>0?'right':'left'):(dy>0?'down':'up');const run=keysDown.has('shift');let speed=chars[state.char].speed*(run?1.38:1)*(state.boost>0?1.22:1);let nx=state.x+dx*speed*dt,ny=state.y+dy*speed*dt;
    if(!blocked(nx,state.y))state.x=nx;if(!blocked(state.x,ny))state.y=ny;
  }
  state.x=Math.max(35,Math.min(W-35,state.x));state.y=Math.max(35,Math.min(H-35,state.y));
  const w=canvas.clientWidth,h=canvas.clientHeight;state.camera.x=Math.max(0,Math.min(W-w,state.x-w/2));state.camera.y=Math.max(0,Math.min(H-h,state.y-h/2));
  const nearby=nearestThing();$('#nearbyPrompt').classList.toggle('visible',!!nearby);if(nearby){$('#nearbyText').textContent=nearby.type==='glow'?'Gather glowcap':nearby.type==='berry'?'Pick berries':nearby.name||nearby.label||'Look closer';}
  $('#locationName').textContent=state.x>2050?'Whispering Creek':state.y<600?'Sunset Rise':state.x<1050?'Fernway Meadow':state.y>1200?'Mossy Hollow':'Old Bridge Trail';
  $('#clock').textContent=state.elapsed>90?'5:08 PM':state.elapsed>35?'4:44 PM':'4:20 PM';
}
function blocked(x,y){
  for(const t of trees){const d=Math.hypot(x-t.x,y-(t.y+5));if(d<t.r*.72+9)return true;}
  // Creek is impassable except at the wooden crossing.
  if(inCreek(x,y)&&!(x>1080&&x<1265&&y>820&&y<1045))return true;
  return false;
}
function inCreek(x,y){const center=1020+Math.sin((x-700)/420)*230+(x-700)*.12;return x>950&&x<2100&&Math.abs(y-center)<38;}

