input.newString:
function inCreek(x,y){const center=780+Math.sin((x-700)/500)*150+(x-700)*.08;return x>900&&x<2150&&Math.abs(y-center)<38;}
function creekY(x){return 780+Math.sin((x-700)/500)*150+(x-700)*.08;}
function draw(){
  const w=canvas.clientWidth,h=canvas.clientHeight;if(!w||!h)return;
  ctx.clearRect(0,0,w,h);ctx.save();ctx.translate(-state.camera.x,-state.camera.y);
  // layered meadow greens
  ctx.fillStyle='#87ad70';ctx.fillRect(0,0,W,H);
  const patches=[{x:400,y:550,rx:600,ry:320,c:'#8eb77a'},{x:1850,y:500,rx:650,ry:360,c:'#82a96d'},{x:1550,y:1540,rx:900,ry:390,c:'#7fa66e'},{x:210,y:1540,rx:520,ry:470,c:'#91b47b'},{x:1300,y:1000,rx:500,ry:360,c:'#85ad72'}];
  patches.forEach(p=>{ctx.fillStyle=p.c;ctx.beginPath();ctx.ellipse(p.x,p.y,p.rx,p.ry,0,0,Math.PI*2);ctx.fill()});
  // sunlit banks and wild grasses
  flowers.forEach(f=>{if(f.x<state.camera.x-10||f.x>state.camera.x+w+10||f.y<state.camera.y-10||f.y>state.camera.y+h+10)return;ctx.globalAlpha=.35+f.k*.35;ctx.fillStyle=f.k>.65?'#f4e3a8':f.k>.32?'#e4f0c4':'#c6da9b';ctx.beginPath();ctx.arc(f.x,f.y,f.s,0,Math.PI*2);ctx.fill();});ctx.globalAlpha=1;
  drawTrail();drawCreek();drawBridge();drawBuildings();drawProps();
  berryBushes.forEach(b=>drawBush(b));glows.forEach(g=>{if(!g.taken)drawGlow(g)});
  npcs.forEach(n=>drawPerson(n.x,n.y,n.color,n.hat,n.glyph,false));
  trees.forEach(t=>{if(t.x<state.camera.x-70||t.x>state.camera.x+w+70||t.y<state.camera.y-85||t.y>state.camera.y+h+70)return;drawTree(t)});
  drawPerson(state.x,state.y,chars[state.char].color,chars[state.char].hat,chars[state.char].glyph,true);
  ctx.restore();drawMini();
}
function drawTrail(){
  ctx.lineCap='round';ctx.lineJoin='round';
  ctx.beginPath();ctx.moveTo(170,990);ctx.bezierCurveTo(390,980,520,850,760,875);ctx.bezierCurveTo(910,892,1000,1000,1150,995);ctx.bezierCurveTo(1390,970,1460,760,1660,745);ctx.bezierCurveTo(1870,730,1990,865,2160,875);ctx.bezierCurveTo(2300,890,2450,720,2630,690);
  ctx.strokeStyle='#779266';ctx.lineWidth=86;ctx.stroke();ctx.strokeStyle='#c5b88b';ctx.lineWidth=66;ctx.stroke();ctx.strokeStyle='#d3c59a';ctx.lineWidth=54;ctx.stroke();
