import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js';

export function createWorld3D(canvas, dimensions) {
  const { width, height } = dimensions;
  const scale = 0.045;
  const scene = new THREE.Scene();
  const sky = new THREE.Color('#a9c5bd');
  scene.background = sky;
  scene.fog = new THREE.FogExp2('#a9c5bd', 0.0085);

  const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: false, powerPreference: 'high-performance' });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.5));
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.12;
  const camera = new THREE.PerspectiveCamera(43, 1, 0.1, 260);
  const hemi = new THREE.HemisphereLight('#e4f4ee', '#455b3e', 2.2);
  scene.add(hemi);
  const sun = new THREE.DirectionalLight('#ffe3b4', 3.2);
  sun.position.set(-38, 62, -28);
  sun.castShadow = true;
  sun.shadow.mapSize.set(1024, 1024);
  sun.shadow.camera.left = -48; sun.shadow.camera.right = 48;
  sun.shadow.camera.top = 48; sun.shadow.camera.bottom = -48;
  sun.shadow.bias = -0.0004;
  scene.add(sun, sun.target);

  const world = (x, y, lift = 0) => new THREE.Vector3((x - width / 2) * scale, terrainHeight(x, y) + lift, (y - height / 2) * scale);
  function terrainHeight(x, y) {
    return 0.24 * Math.sin(x * 0.0031) * Math.cos(y * 0.0025)
      + 0.15 * Math.sin((x + y) * 0.006)
      + 0.18 * Math.sin(x * 0.0017 + 1.8) * Math.sin(y * 0.0019);
  }
  const seeded = (seed) => { let n = seed | 0; return () => { n = (n * 1664525 + 1013904223) | 0; return (n >>> 0) / 4294967296; }; };
  const random = seeded(1947);

  const terrainGeo = new THREE.PlaneGeometry(width * scale, height * scale, 100, 74);
  terrainGeo.rotateX(-Math.PI / 2);
  const positions = terrainGeo.attributes.position;
  const colors = [];
  const low = new THREE.Color('#536b49'), mid = new THREE.Color('#789264'), high = new THREE.Color('#a1aa72');
  for (let i = 0; i < positions.count; i++) {
    const x = positions.getX(i) / scale + width / 2;
    const y = positions.getZ(i) / scale + height / 2;
    positions.setY(i, terrainHeight(x, y));
    const patch = Math.sin(x * 0.009) * Math.sin(y * 0.008) * 0.5 + 0.5;
    const c = low.clone().lerp(mid, 0.45 + patch * 0.46).lerp(high, Math.max(0, terrainHeight(x, y)) * 0.12);
    colors.push(c.r, c.g, c.b);
  }
  terrainGeo.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
  terrainGeo.computeVertexNormals();
  const ground = new THREE.Mesh(terrainGeo, new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 1 }));
  ground.receiveShadow = true;
  scene.add(ground);

  function path(points, radius, material, segments = 180) {
    const curve = new THREE.CatmullRomCurve3(points.map(([x, y]) => world(x, y, 0.05)));
    const mesh = new THREE.Mesh(new THREE.TubeGeometry(curve, segments, radius, 7, false), material);
    mesh.receiveShadow = true;
    scene.add(mesh);
    return mesh;
  }
  const trailBase = new THREE.MeshStandardMaterial({ color: '#596c48', roughness: 1 });
  const trailTop = new THREE.MeshStandardMaterial({ color: '#c4b68b', roughness: 0.96 });
  const trailCenter = new THREE.MeshStandardMaterial({ color: '#d8c99a', roughness: 1 });
  const trail = [[170,990],[360,968],[520,900],[760,875],[920,900],[1030,970],[1150,995],[1350,930],[1490,790],[1660,745],[1850,740],[2010,840],[2160,875],[2310,850],[2450,735],[2630,690]];
  path(trail, 1.88, trailBase); path(trail, 1.43, trailTop); path(trail, 1.17, trailCenter);
  path([[1780,746],[1780,655],[1780,505]], 1.06, trailTop, 60);
