function makePerson(color, hatColor, trimColor = '#f6e8bd', style = 'pip') {
  const group = new THREE.Group();
  const mat = (c, roughness = 0.84, metalness = 0) => new THREE.MeshStandardMaterial({ color: c, roughness, metalness });
  const coat = mat(color), trim = mat(trimColor), hatMat = mat(hatColor), skin = mat('#d7a982', 0.92);
  const hair = mat(style === 'moss' ? '#3d3028' : style === 'wren' ? '#473b46' : '#654334');
  const trousers = mat(style === 'moss' ? '#384d43' : style === 'wren' ? '#454356' : '#52604a');
  const boots = mat('#493c34', 0.96), leather = mat('#79553b'), metal = mat('#d5b66e', 0.45, 0.35);
  const addMesh = (parent, geometry, material, position, scale) => {
    const mesh = new THREE.Mesh(geometry, material); mesh.position.set(...position);
    if (scale) mesh.scale.set(...scale); mesh.castShadow = true; mesh.receiveShadow = true; parent.add(mesh); return mesh;
  };
  const torso = addMesh(group, new THREE.CapsuleGeometry(0.25, 0.43, 5, 10), coat, [0, 0.93, 0], [1, 1, 0.83]);
  // Layered, character-specific garments and stitched details make each silhouette distinct.
  if (style === 'moss') {
    addMesh(group, new THREE.CylinderGeometry(0.32, 0.23, 0.28, 10), leather, [0, 0.53, 0], [1, 1, 0.85]);
    const cape = addMesh(group, new THREE.ConeGeometry(0.44, 0.72, 5), trim, [0, 0.79, -0.17], [1, 1, 0.3]); cape.rotation.x = -0.12;
    addMesh(group, new THREE.TorusGeometry(0.28, 0.045, 6, 16), trim, [0, 1.16, 0], [1, 0.65, 1]);
  } else if (style === 'wren') {
    addMesh(group, new THREE.CylinderGeometry(0.3, 0.22, 0.34, 8), trousers, [0, 0.55, 0], [1, 1, 0.85]);
    addMesh(group, new THREE.BoxGeometry(0.08, 0.54, 0.06), trim, [0, 0.92, 0.216]);
    addMesh(group, new THREE.SphereGeometry(0.15, 8, 6), leather, [0.27, 0.79, -0.04], [1, 1, 0.52]);
    addMesh(group, new THREE.TorusGeometry(0.29, 0.035, 6, 18), trim, [0, 1.11, 0], [1, 0.65, 0.9]);
  } else {
    addMesh(group, new THREE.CylinderGeometry(0.3, 0.22, 0.32, 9), leather, [0, 0.54, 0], [1, 1, 0.86]);
    addMesh(group, new THREE.BoxGeometry(0.12, 0.42, 0.055), trim, [0, 0.91, 0.22]);
    addMesh(group, new THREE.SphereGeometry(0.16, 8, 6), leather, [-0.27, 0.8, -0.06], [1, 1, 0.56]);
    addMesh(group, new THREE.TorusGeometry(0.29, 0.035, 6, 18), trim, [0, 1.1, 0], [1, 0.6, 0.9]);
  }
  // Neck, shaped head, ears, nose, hairline and expressive eyes.
  addMesh(group, new THREE.CylinderGeometry(0.09, 0.1, 0.16, 9), skin, [0, 1.2, 0]);
  addMesh(group, new THREE.SphereGeometry(0.235, 16, 12), skin, [0, 1.49, 0.015], [0.9, 1.12, 0.88]);
  addMesh(group, new THREE.SphereGeometry(0.19, 12, 8), hair, [0, 1.63, -0.045], [1, 0.65, 0.95]);
  for (const side of [-1, 1]) {
    addMesh(group, new THREE.SphereGeometry(0.055, 8, 6), skin, [side * 0.21, 1.48, 0]);
    addMesh(group, new THREE.SphereGeometry(0.03, 7, 5), new THREE.MeshBasicMaterial({ color: '#f2d5bb' }), [side * 0.225, 1.48, 0.01]);
    addMesh(group, new THREE.SphereGeometry(0.027, 8, 6), new THREE.MeshBasicMaterial({ color: '#43362f' }), [side * 0.09, 1.51, 0.202]);
    const brow = addMesh(group, new THREE.BoxGeometry(0.075, 0.018, 0.025), hair, [side * 0.09, 1.56, 0.2]); brow.rotation.z = side * -0.12;
  }
  addMesh(group, new THREE.ConeGeometry(0.045, 0.13, 7), skin, [0, 1.46, 0.22], [0.75, 1, 0.75]).rotation.x = Math.PI / 2;
  // A soft field hat with a broad brim, pin and character-specific crown.
  addMesh(group, new THREE.CylinderGeometry(0.33, 0.36, 0.055, 16), hatMat, [0, 1.72, 0]);
  addMesh(group, new THREE.CylinderGeometry(0.19, 0.23, 0.24, 12), hatMat, [0, 1.85, 0]);
  addMesh(group, new THREE.SphereGeometry(0.055, 8, 6), metal, [0.16, 1.73, 0.27]);
  // Articulated shoulders, elbows, hips and knees for a readable gait.
  const upperArms = [], lowerArms = [], upperLegs = [], lowerLegs = [];
  for (const side of [-1, 1]) {
    const shoulder = new THREE.Group(); shoulder.position.set(side * 0.29, 1.12, 0); group.add(shoulder); upperArms.push(shoulder);
    addMesh(shoulder, new THREE.CapsuleGeometry(0.095, 0.25, 4, 8), coat, [0, -0.19, 0]);
    const elbow = new THREE.Group(); elbow.position.y = -0.38; shoulder.add(elbow); lowerArms.push(elbow);
    addMesh(elbow, new THREE.CapsuleGeometry(0.075, 0.23, 4, 8), style === 'wren' ? trim : coat, [0, -0.17, 0]);
    addMesh(elbow, new THREE.SphereGeometry(0.075, 8, 6), skin, [0, -0.35, 0.02]);
    const hip = new THREE.Group(); hip.position.set(side * 0.14, 0.58, 0); group.add(hip); upperLegs.push(hip);
    addMesh(hip, new THREE.CapsuleGeometry(0.115, 0.24, 4, 8), trousers, [0, -0.2, 0]);
    const knee = new THREE.Group(); knee.position.y = -0.39; hip.add(knee); lowerLegs.push(knee);
    addMesh(knee, new THREE.CapsuleGeometry(0.085, 0.23, 4, 8), trousers, [0, -0.16, 0]);
    addMesh(knee, new THREE.SphereGeometry(0.105, 9, 6), boots, [0, -0.34, 0.1], [1, 0.72, 1.35]);
  }
  const shadow = new THREE.Mesh(new THREE.CircleGeometry(0.52, 24), new THREE.MeshBasicMaterial({ color: '#253b2b', transparent: true, opacity: 0.24, depthWrite: false }));
  shadow.rotation.x = -Math.PI / 2; shadow.position.y = 0.018; group.add(shadow);
  group.userData.rig = { upperArms, lowerArms, upperLegs, lowerLegs, torso, shadow, style };
  group.userData.materials = { coat, trim, hatMat };
  scene.add(group); return group;
}
const npcSpecs = [
  { x: 1170, y: 900, color: '#bd8666', hat: '#e7c27c', trim: '#f2d9a8', style: 'moss' },
  { x: 1780, y: 650, color: '#788fa0', hat: '#d7d9bb', trim: '#dde9dd', style: 'wren' },
  { x: 2200, y: 1340, color: '#987e9c', hat: '#ecc5a0', trim: '#f4d6cf', style: 'pip' }
];
const npcs = npcSpecs.map(n => { const p = world(n.x, n.y); const model = makePerson(n.color, n.hat, n.trim, n.style); model.position.set(p.x, p.y, p.z); return model; });
const player = makePerson('#e98b68', '#f0c77b', '#f6e8bd', 'pip');
let playerColor = '#e98b68', playerHat = '#f0c77b', playerTrim = '#f6e8bd', playerStyle = 'pip';
function recolorPerson(group, character) {
  const { color, hat, trim = '#f6e8bd', id = 'pip' } = character;
  const mats = group.userData.materials;
  mats.coat.color.set(color); mats.hatMat.color.set(hat); mats.trim.color.set(trim);
  playerColor = color; playerHat = hat; playerTrim = trim; playerStyle = id;
}

