input.newString:
function update(state, dt, character) {
  dt = Math.min(0.05, Math.max(0, dt || 0));
  time += dt;
  if (character && (character.id !== playerStyle || character.color !== playerColor || character.hat !== playerHat || character.trim !== playerTrim)) setCharacter(character);
  const p = world(state.x, state.y, 0);
  const active = state.running && !state.paused && !state.dialogueOpen;
  const keys = state.keys || {};
  const moving = active && (keys.w || keys.a || keys.s || keys.d);
  const previousHeight = jumpHeight;
  if (active) {
    jumpHeight = Math.max(0, jumpHeight + jumpVelocity * dt);
    jumpVelocity -= 16 * dt;
    if (jumpHeight === 0) {
      jumpVelocity = 0;
      if (previousHeight > 0) landingUntil = time + 0.45;
    }
  }
  player.position.set(p.x, p.y + jumpHeight, p.z);
  const rig = player.userData.rig;
  const gait = moving ? Math.sin(time * (keys.run ? 13 : 9)) : 0;
  const idle = Math.sin(time * 1.5) * 0.035;
  rig.torso.rotation.x = moving ? Math.abs(gait) * 0.035 : idle;
  rig.upperArms.forEach((arm, i) => {
    arm.rotation.x = moving ? gait * (i ? -0.55 : 0.55) : Math.sin(time * 1.4 + i) * 0.025;
    arm.rotation.z = 0;
  });
  rig.lowerArms.forEach((arm, i) => { arm.rotation.x = moving ? Math.max(0, -gait) * 0.35 : 0; arm.rotation.z = 0; });
  rig.upperLegs.forEach((leg, i) => { leg.rotation.x = moving ? gait * (i ? -0.62 : 0.62) : 0; });
  rig.lowerLegs.forEach((leg, i) => { leg.rotation.x = moving ? Math.max(0, i ? gait : -gait) * 0.72 : 0; });
  if (time < actionUntil && actionName === 'wave') {
    const wave = Math.sin((actionUntil - time) * 22) * 0.18;
    rig.upperArms[1].rotation.z = 2.75 + wave;
    rig.lowerArms[1].rotation.z = 0.55 + wave * 1.6;
  } else actionName = '';
  const facing = { down: 0, up: Math.PI, left: -Math.PI / 2, right: Math.PI / 2 }[state.facing] || 0;
  player.rotation.y = facing;
  const grounded = jumpHeight < 0.04;
  rig.shadow.position.y = -jumpHeight + 0.018;
  const shadowScale = 1 - Math.min(0.42, jumpHeight * 0.22);
  rig.shadow.scale.set(shadowScale, shadowScale, shadowScale);
  rig.shadow.material.opacity = 0.24 * shadowScale;
  player.position.y += moving && grounded ? Math.abs(gait) * 0.045 : idle;
  if (time < landingUntil) {
    landingRing.visible = true;
    landingRing.position.set(p.x, p.y + 0.035, p.z);
    const progress = 1 - (landingUntil - time) / 0.45;
    landingRing.scale.setScalar(0.7 + progress * 2.8);
    landingRing.material.opacity = 0.48 * (1 - progress);
  } else { landingRing.visible = false; landingRing.material.opacity = 0; }
  camera.position.lerp(new THREE.Vector3(p.x, p.y + 22, p.z + 27), 0.08);

