58:     const target = alive.slice().sort((a, b) => distance(a) - distance(b))[0];
59:     $('#targetCard').classList.toggle('visible', !!target && state.running && !state.ended);
60:     if (target) {
61:       $('#targetName').textContent = target.name;
62:       $('#targetHealth').style.width = `${100 * target.hp / target.maxHp}%`;
63:     }
64:   }
65:   function distance(enemy) { return Math.hypot(enemy.x - state.x, enemy.z - state.z); }
66:   function targetEnemy(range = 20) {
67:     return state.enemies.filter(e => !e.dead && distance(e) < range).sort((a, b) => distance(a) - distance(b))[0];
68:   }
69:   function hit(enemy, damage, push = 1) {
70:     enemy.hp -= damage; enemy.stagger = 0.26;
71:     const dx = enemy.x - state.x, dz = enemy.z - state.z, d = Math.max(0.01, Math.hypot(dx, dz));
72:     enemy.x += dx / d * push; enemy.z += dz / d * push;
73:     state.energy = Math.min(100, state.energy + 7);
74:     state.combo++; state.comboTimer = 2.3;
75:     world.action('hit', enemy.id);
76:     if (enemy.hp <= 0) {
77:       enemy.dead = true; state.reward += 35 + state.wave * 5; state.energy = Math.min(100, state.energy + 9);
78:       toast(`${enemy.name} disrupted · +${35 + state.wave * 5} CRED`); tone(740, 0.13);
79:     } else tone(280 + Math.random() * 120, 0.055);
