91:     const range = kind === 'ex' ? 6.2 : kind === 'skill' ? 4.5 : 3.0;
92:     const arc = kind === 'attack' ? 2.0 : 2.8;
93:     state.enemies.forEach(e => {
94:       if (e.dead || distance(e) > range) return;
95:       const dx = e.x - state.x, dz = e.z - state.z, d = Math.max(0.01, Math.hypot(dx, dz));
96:       const dot = dx / d * state.facing.x + dz / d * state.facing.z;
97:       if (dot > (kind === 'ex' ? -0.15 : -0.05)) { hitIds.add(e.id); hit(e, kind === 'ex' ? 115 : kind === 'skill' ? 43 : 24 + Math.min(state.combo, 8) * 2, kind === 'ex' ? 2.6 : skill ? 1.8 : 0.9); }
98:     });
99:     world.action(kind, null, state.facing);
100:     if (kind === 'ex') { announce('EX DRIVE', 1.1); tone(130, 0.3); }
101:     else if (kind === 'skill') tone(170, 0.14);
102:   }
103:   function dodge() {
104:     if (!state.running || state.paused || state.ended || state.dodge > 0) return;
105:     const dx = (keys.has('a') || keys.has('arrowleft') ? -1 : 0) + (keys.has('d') || keys.has('arrowright') ? 1 : 0);
106:     const dz = (keys.has('w') || keys.has('arrowup') ? -1 : 0) + (keys.has('s') || keys.has('arrowdown') ? 1 : 0);
107:     if (dx || dz) { const len = Math.hypot(dx, dz); state.facing = { x: dx / len, z: dz / len }; }
108:     state.x += state.facing.x * 2.7; state.z += state.facing.z * 2.7;
109:     state.dodge = 0.42; state.invulnerable = 0.56; state.comboTimer = Math.max(state.comboTimer, 0.8);
110:     world.action('dodge', null, state.facing); tone(660, 0.07);
111:   }
112:   function incoming(enemy, dt) {
113:     const d = distance(enemy);
114:     if (enemy.stagger > 0) { enemy.stagger -= dt; return; }
115:     if (enemy.windup > 0) {
116:       enemy.windup -= dt;
117:       if (enemy.windup <= 0 && d < 2.2 && state.invulnerable <= 0) {
118:         state.health = Math.max(0, state.health - (enemy.type === 2 ? 18 : 10));
119:         state.combo = 0; $('#damageFlash').classList.remove('flash'); void $('#damageFlash').offsetWidth; $('#damageFlash').classList.add('flash');
120:         world.action('player-hit'); updateHUD(); tone(90, 0.12);
121:       }
122:       return;
123:     }
124:     if (d > 2.15) {
125:       const vx = (state.x - enemy.x) / Math.max(d, 0.01), vz = (state.z - enemy.z) / Math.max(d, 0.01);
126:       enemy.x += vx * enemy.speed * dt; enemy.z += vz * enemy.speed * dt;
127:     } else if (enemy.attack <= 0) {
128:       enemy.windup = 0.58; enemy.attack = 1.5 + Math.random() * 0.5;
129:       world.action('enemy-windup', enemy.id);
