135:     $('#resultOverlay').classList.remove('hidden');
136:     $('#resultEyebrow').textContent = won ? 'SECTOR CLEARED' : 'AGENT DOWN';
137:     $('#resultTitle').textContent = won ? 'Clean work.' : 'Run it back.';
138:     $('#resultCopy').textContent = won ? `Wave ${state.wave} cleared. The overpass is quiet. For now.` : 'The rift is still open. Reset, reload, and take the fight back.';
139:     $('#continueBtn').textContent = won ? 'NEXT WAVE ↗' : 'RETRY OPERATION ↗';
