143:     if (state.messageTimer > 0 && (state.messageTimer -= dt) <= 0) $('#centerMessage').classList.remove('show');
144:     if (!state.running || state.paused || state.ended) return;
145:     state.skillCooldown = Math.max(0, (state.skillCooldown || 0) - dt);
146:     state.invulnerable = Math.max(0, state.invulnerable - dt);
147:     state.dodge = Math.max(0, state.dodge - dt);
148:     if (state.attack && (state.attack.timer -= dt) <= 0) state.attack = null;
149:     if (state.comboTimer > 0 && (state.comboTimer -= dt) <= 0) state.combo = 0;
150:     let dx = (keys.has('d') || keys.has('arrowright') ? 1 : 0) - (keys.has('a') || keys.has('arrowleft') ? 1 : 0);
