197:     const up = e => { e.preventDefault(); keys.delete(key); };
198:     button.addEventListener('pointerdown', down); button.addEventListener('pointerup', up); button.addEventListener('pointercancel', up); button.addEventListener('lostpointercapture', up);
199:   });
200:   window.addEventListener('keydown', e => {
201:     const k = e.key.toLowerCase();
202:     if ([' ', 'arrowup', 'arrowdown', 'arrowleft', 'arrowright'].includes(k)) e.preventDefault();
203:     if (k === 'escape') { togglePause(); return; }
204:     if (e.repeat) return;
205:     if (k === 'j') attack('attack'); else if (k === 'k') attack('skill'); else if (k === 'r') attack('ex'); else if (k === ' ') dodge();
206:     keys.add(k);
207:   });
208:   window.addEventListener('keyup', e => keys.delete(e.key.toLowerCase()));
209:   window.addEventListener('blur', () => keys.clear());
210:   updateHUD(); requestAnimationFrame(frame);
211: })();

