3: export function createWorld3D(canvas) {
4:   const scene = new THREE.Scene();
5:   scene.background = new THREE.Color('#10131e');
6:   scene.fog = new THREE.Fog('#10131e', 32, 82);
7: 
8:   const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: false, powerPreference: 'high-performance' });
9:   renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.5));
10:   renderer.shadowMap.enabled = true;
11:   renderer.shadowMap.type = THREE.PCFSoftShadowMap;
12:   renderer.outputColorSpace = THREE.SRGBColorSpace;
13:   renderer.toneMapping = THREE.ACESFilmicToneMapping;
14:   renderer.toneMappingExposure = 1.2;
15: 
16:   const camera = new THREE.PerspectiveCamera(42, 1, 0.1, 120);
17:   scene.add(new THREE.HemisphereLight('#a9c8e8', '#181923', 1.55));
18:   const keyLight = new THREE.DirectionalLight('#e2e8ff', 2.4);
19:   keyLight.position.set(-12, 24, 9); keyLight.castShadow = true;
20:   keyLight.shadow.mapSize.set(1024, 1024);
21:   keyLight.shadow.camera.left = -25; keyLight.shadow.camera.right = 25;
22:   keyLight.shadow.camera.top = 25; keyLight.shadow.camera.bottom = -25;
23:   keyLight.shadow.bias = -0.0004; scene.add(keyLight, keyLight.target);
24: 
25:   const mat = (color, roughness = 0.72, metalness = 0, emissive = '#000000', intensity = 0) => new THREE.MeshStandardMaterial({ color, roughness, metalness, emissive, emissiveIntensity: intensity });
26:   const concrete = mat('#292d39', 0.9), asphalt = mat('#20232e', 0.82), darkMetal = mat('#111722', 0.45, 0.65);
27:   const cyan = mat('#62edff', 0.28, 0.2, '#0aaecb', 2.2), pink = mat('#ff4a9d', 0.32, 0.15, '#dd1265', 1.7);
28:   const amber = mat('#ffc66e', 0.4, 0.15, '#cc6a20', 1.15), whiteGlow = mat('#d9faff', 0.3, 0.1, '#9deaff', 1.4);
29: 
30:   function box(parent, size, position, material, cast = true) {
31:     const mesh = new THREE.Mesh(new THREE.BoxGeometry(...size), material);
32:     mesh.position.set(...position); mesh.castShadow = cast; mesh.receiveShadow = true; parent.add(mesh); return mesh;
33:   }
34:   function cylinder(parent, radiusTop, radiusBottom, height, position, material, sides = 10) {
35:     const mesh = new THREE.Mesh(new THREE.CylinderGeometry(radiusTop, radiusBottom, height, sides), material);
36:     mesh.position.set(...position); mesh.castShadow = true; parent.add(mesh); return mesh;
37:   }
38:   function areaLight(color, intensity, distance, position) {
39:     const light = new THREE.PointLight(color, intensity, distance, 2);
40:     light.position.set(...position); scene.add(light); return light;
41:   }
42: 
43:   // A compact rain-darkened intersection, framed by an elevated rail and tall city blocks.
44:   const floor = new THREE.Mesh(new THREE.PlaneGeometry(100, 100), concrete);
45:   floor.rotation.x = -Math.PI / 2; floor.position.y = -0.18; floor.receiveShadow = true; scene.add(floor);
46:   const arena = new THREE.Mesh(new THREE.PlaneGeometry(32, 24), asphalt);
47:   arena.rotation.x = -Math.PI / 2; arena.position.y = -0.12; arena.receiveShadow = true; scene.add(arena);
48:   const roadLine = mat('#68707c', 0.72, 0.05, '#303744', 0.16);
49:   for (let z = -10; z <= 10; z += 5) {
50:     box(scene, [25, 0.018, 0.035], [0, -0.095, z], roadLine, false);
51:   }
52:   for (const x of [-14.8, 14.8]) {
53:     box(scene, [0.12, 0.05, 21], [x, -0.02, 0], cyan, false);
54:   }
55:   for (const z of [-10.8, 10.8]) {
56:     box(scene, [30, 0.05, 0.12], [0, -0.02, z], pink, false);
57:   }
58:   // Crosswalks, inset drains, and luminous lane studs give the ground readable scale.
59:   for (let i = 0; i < 7; i++) {
60:     box(scene, [0.34, 0.025, 2.1], [-13.1 + i * 0.72, -0.09, -7.65], roadLine, false);
61:     box(scene, [0.34, 0.025, 2.1], [8.9 + i * 0.72, -0.09, 7.65], roadLine, false);
62:   }
63:   for (const z of [-8.7, 8.7]) for (let x = -12; x <= 12; x += 4) {
64:     const stud = new THREE.Mesh(new THREE.BoxGeometry(0.13, 0.035, 0.13), x % 8 ? cyan : pink);
65:     stud.position.set(x, -0.04, z); scene.add(stud);
66:   }
67: 
68:   // Procedural skyline: dark facades, glowing window bands, rooftop tanks and signage.
69:   const buildingMats = ['#262b3a', '#202735', '#2d2939', '#1d3039'].map(c => mat(c, 0.86, 0.12));
70:   const windowMats = ['#4ed9ed', '#ff4b9b', '#e9b86c', '#9c89ff'].map((c, i) => mat(c, 0.3, 0.15, c, i === 1 ? 1.2 : 0.85));
71:   const buildings = [
72:     [-24, -23, 12, 19, 10], [-8, -24, 11, 25, 12], [9, -23, 14, 17, 10], [25, -22, 12, 22, 13],
73:     [-25, 1, 12, 17, 12], [25, 1, 13, 24, 12], [-23, 23, 15, 21, 12], [-7, 24, 11, 16, 11], [10, 23, 15, 25, 12], [26, 22, 12, 18, 12]
74:   ];
75:   buildings.forEach(([x, z, w, h, d], index) => {
76:     const group = new THREE.Group(); group.position.set(x, 0, z); scene.add(group);
