const { createRequire } = require('node:module');
const { readFileSync, mkdirSync } = require('node:fs');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions });
  const errors = [];
  try {
    const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
    page.on('pageerror', e => errors.push(e.message));
    page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
    await page.goto('http://127.0.0.1:3000', { waitUntil: 'load' });
    await page.locator('#playBtn').click();
    await page.waitForTimeout(1200);
    if (!await page.locator('#startOverlay').evaluate(el => el.classList.contains('hidden'))) throw new Error('Deploy overlay did not close');
    await page.keyboard.down('w'); await page.waitForTimeout(400); await page.keyboard.up('w');
    await page.keyboard.press('j'); await page.waitForTimeout(250);
    await page.keyboard.press('Escape');
    if (await page.locator('#pauseOverlay').evaluate(el => el.classList.contains('hidden'))) throw new Error('Pause overlay did not open');
    await page.locator('#resumeBtn').click();
    await page.waitForTimeout(350);
    mkdirSync('screenshots', { recursive: true });
    await page.screenshot({ path: 'screenshots/neonbreak-verified.jpg', type: 'jpeg', quality: 90 });
    const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });
    mobile.on('pageerror', e => errors.push(e.message));
    await mobile.goto('http://127.0.0.1:3000', { waitUntil: 'load' });
    await mobile.locator('#playBtn').click();
    await mobile.waitForTimeout(300);
    if (!await mobile.locator('#touchAttack').isVisible()) throw new Error('Mobile attack control is not visible');
    if (errors.length) throw new Error(`Browser errors: ${errors.join('; ')}`);
    console.log('PASS desktop deploy/move/attack/pause/resume; mobile deploy/touch controls; no browser errors');
  } finally { await browser.close(); }
})().catch(e => { console.error(e); process.exitCode = 1; });

